-- Synthetic identities in an isolated database only. Works against real schema.
BEGIN;
-- Mirror production Auth cascades missing from the minimal composed fixture.
ALTER TABLE public.team_memberships ADD COLUMN IF NOT EXISTS joined_at timestamptz DEFAULT now();
ALTER TABLE public.spaces ADD CONSTRAINT account_qa_space_auth FOREIGN KEY(user_id) REFERENCES auth.users(id) ON DELETE CASCADE NOT VALID;
ALTER TABLE public.bins ADD CONSTRAINT account_qa_bin_auth FOREIGN KEY(user_id) REFERENCES auth.users(id) ON DELETE CASCADE NOT VALID;
CREATE UNIQUE INDEX IF NOT EXISTS bins_user_space_name_ci_idx ON public.bins(user_id,space_id,lower(btrim(name)));
ALTER TABLE public.documents ADD COLUMN IF NOT EXISTS file_type text, ADD COLUMN IF NOT EXISTS mime_type text, ADD COLUMN IF NOT EXISTS size_bytes bigint;
SELECT set_config('request.jwt.claims','{}',true);
SELECT set_config('request.headers','{}',true);
CREATE OR REPLACE FUNCTION pg_temp.account_check(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAILED: %',label; END IF; RAISE NOTICE 'PASS: %',label; END $$;
DO $$
DECLARE a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid();
 org uuid; ws uuid; inv uuid; s uuid; bi uuid; it uuid; doc uuid; private_doc uuid; task uuid; personal uuid; ownerws uuid; ownerinv uuid; solo uuid; independent uuid;
 photo text; r jsonb; test_role text;
BEGIN
 FOR test_role IN SELECT unnest(ARRAY['admin','member','viewer']) LOOP
 SET CONSTRAINTS ALL DEFERRED;
 a:=gen_random_uuid(); b:=gen_random_uuid(); outsider:=gen_random_uuid();
 INSERT INTO auth.users(id,email,email_confirmed_at) VALUES(a,a||'@example.invalid',now()),(b,b||'@example.invalid',now()),(outsider,outsider||'@example.invalid',now());
 org:=(public.findez_manage_collaboration(a,'organization_create','{"name":"Account deletion QA"}')->>'organization_id')::uuid;
 INSERT INTO public.app_organization_members VALUES(org,b,'admin');
 ws:=(public.findez_manage_collaboration(a,'workspace_create',jsonb_build_object('organization_id',org,'name','Shared workshop'))->>'team_id')::uuid;
 INSERT INTO public.team_memberships(team_id,user_id,role) VALUES(ws,b,'member');
 inv:=(public.findez_create_inventory(a,ws,'Shared parts','workspace')->>'inventory_id')::uuid;
 INSERT INTO public.spaces(user_id,inventory_id,name) VALUES(b,inv,'Contributor shelf') RETURNING id INTO s;
 -- Reproduce historical same-name rows allowed by the owner-qualified index.
 ALTER TABLE public.spaces DISABLE TRIGGER spaces_assign_inventory;
 INSERT INTO public.spaces(user_id,inventory_id,name) VALUES(a,inv,'Contributor shelf');
 ALTER TABLE public.spaces ENABLE TRIGGER spaces_assign_inventory;
 INSERT INTO public.bins(user_id,inventory_id,space_id,name) VALUES(b,inv,s,'Contributor bin') RETURNING id INTO bi;
 INSERT INTO public.bins(user_id,inventory_id,space_id,name) VALUES(a,inv,s,'Contributor bin');
 photo:='https://storage.invalid/storage/v1/object/public/item-images/'||b||'/shared.jpg';
 INSERT INTO public.items(user_id,inventory_id,space_id,name,category,quantity,location,image_url) VALUES(b,inv,s,'Shared item','Tools',7,'Contributor shelf',photo) RETURNING item_id INTO it;
 INSERT INTO public.item_events(item_id,user_id,inventory_id,event_type,content,image_url) VALUES(it,b,inv,'photo','Original',photo);
 INSERT INTO public.documents(user_id,inventory_id,filename,storage_path,inventory_visibility,file_type,mime_type,size_bytes) VALUES(b,inv,'Shared manual',b||'/docs/shared.pdf','inventory','pdf','application/pdf',10) RETURNING document_id INTO doc;
 INSERT INTO public.documents(user_id,inventory_id,filename,storage_path,inventory_visibility,file_type,mime_type,size_bytes) VALUES(b,inv,'Private note',b||'/docs/private.pdf','personal','pdf','application/pdf',10) RETURNING document_id INTO private_doc;
 INSERT INTO public.team_board_tasks(team_id,created_by,assigned_to,title) VALUES(ws,b,a,'Shared task') RETURNING task_id INTO task;
 personal:=public.findez_default_inventory(b);
 INSERT INTO public.items(user_id,inventory_id,name,category,quantity,location) VALUES(b,personal,'Private item','Tools',1,'Unsorted');
 ownerws:=(public.findez_manage_collaboration(b,'workspace_create',jsonb_build_object('organization_id',org,'name','Admin owned workspace'))->>'team_id')::uuid;
 ownerinv:=(public.findez_create_inventory(b,ownerws,'Admin owned inventory','workspace')->>'inventory_id')::uuid;
 INSERT INTO public.items(user_id,inventory_id,name,category,quantity,location,image_url) VALUES(b,ownerinv,'Retained owned item','Tools',2,'Unsorted',photo);
 solo:=(public.findez_create_legacy_workspace(b,'{"name":"Private workspace","program":"business"}')->>'team_id')::uuid;
 independent:=(public.findez_create_legacy_workspace(b,'{"name":"Independent shared workspace","program":"business"}')->>'team_id')::uuid;
 INSERT INTO public.team_memberships(team_id,user_id,role) VALUES(independent,outsider,'mentor');
 UPDATE public.app_organization_members SET role=CASE WHEN test_role='admin' THEN 'admin' ELSE 'member' END WHERE organization_id=org AND user_id=b;
 UPDATE public.team_memberships SET role=CASE WHEN test_role='viewer' THEN 'viewer' ELSE 'member' END WHERE team_id=ws AND user_id=b;
 PERFORM pg_temp.account_check(public.findez_prepare_account_deletion(a)->>'code'='OWNERSHIP_REQUIRED','organization Owner must transfer');
 BEGIN DELETE FROM auth.users WHERE id=a; RAISE EXCEPTION 'Owner deleted'; EXCEPTION WHEN check_violation THEN NULL; END;
 PERFORM pg_temp.account_check(EXISTS(SELECT 1 FROM auth.users WHERE id=a),'direct Auth deletion also protects organization Owner');
 r:=public.findez_prepare_account_deletion(b);
 PERFORM pg_temp.account_check(r->>'ready'='true','shared contributions do not block '||test_role);
 PERFORM pg_temp.account_check((SELECT user_id=b FROM public.spaces WHERE id=s) AND (SELECT owner_user_id=b FROM public.teams WHERE team_id=ownerws),'preparation does not change ownership');
 PERFORM pg_temp.account_check(NOT public.findez_finish_account_deletion(b),'cleanup cannot start before Auth succeeds');
 EXECUTE 'CREATE TABLE public.account_auth_failure(user_id uuid REFERENCES auth.users(id))';
 INSERT INTO account_auth_failure VALUES(b);
 BEGIN DELETE FROM auth.users WHERE id=b; RAISE EXCEPTION 'Auth failure was ignored'; EXCEPTION WHEN foreign_key_violation THEN NULL; END;
 PERFORM pg_temp.account_check((SELECT user_id=b FROM public.spaces WHERE id=s) AND (SELECT owner_user_id=b FROM public.teams WHERE team_id=ownerws),'failed Auth rolls back all transfers');
 PERFORM pg_temp.account_check(EXISTS(SELECT 1 FROM public.items WHERE inventory_id=personal),'failed Auth preserves private content');
 DROP TABLE account_auth_failure;
 DELETE FROM auth.users WHERE id=b;
 SET CONSTRAINTS ALL IMMEDIATE;
 PERFORM pg_temp.account_check(NOT EXISTS(SELECT 1 FROM auth.users WHERE id=b),'member account deleted');
 PERFORM pg_temp.account_check(public.findez_finish_account_deletion(b),'durable cleanup finishes');
 PERFORM pg_temp.account_check(public.findez_finish_account_deletion(b),'cleanup can safely retry');
 PERFORM pg_temp.account_check(EXISTS(SELECT 1 FROM public.spaces WHERE id=s AND user_id=a),'shared Space survives Auth cascade');
 PERFORM pg_temp.account_check((SELECT count(*)=2 FROM public.spaces WHERE inventory_id=inv),'historical same-name Spaces remain separate');
 PERFORM pg_temp.account_check((SELECT i.location=s.name FROM public.items i JOIN public.spaces s ON s.id=i.space_id WHERE i.item_id=it),'item location follows disambiguated Space');
 PERFORM pg_temp.account_check(EXISTS(SELECT 1 FROM public.bins WHERE id=bi AND user_id=a),'shared bin survives Auth cascade');
 PERFORM pg_temp.account_check((SELECT count(*)=2 FROM public.bins WHERE space_id=s),'same-name bins are retained separately without blocking deletion');
 PERFORM pg_temp.account_check(EXISTS(SELECT 1 FROM public.items WHERE item_id=it AND quantity=7 AND image_url=photo AND user_id=b),'item and creator attribution survive');
 PERFORM pg_temp.account_check(EXISTS(SELECT 1 FROM public.item_events WHERE item_id=it AND image_url=photo),'original photo survives cleanup');
 PERFORM pg_temp.account_check(EXISTS(SELECT 1 FROM public.documents WHERE document_id=doc AND storage_path=b||'/docs/shared.pdf' AND user_id=b),'shared document path/uploader preserved');
 PERFORM pg_temp.account_check(NOT EXISTS(SELECT 1 FROM public.documents WHERE document_id=private_doc),'private document in shared inventory removed');
 PERFORM pg_temp.account_check(EXISTS(SELECT 1 FROM public.team_board_tasks WHERE task_id=task AND created_by=b),'shared task and historical attribution retained');
 PERFORM pg_temp.account_check((SELECT assigned_by IS NULL FROM public.team_board_tasks WHERE task_id=task),'deleted task assigner does not break Auth FK');
 PERFORM pg_temp.account_check((SELECT join_code_created_by IS NULL FROM public.teams WHERE team_id=ownerws),'deleted invite issuer does not break Auth FK');
 PERFORM pg_temp.account_check((SELECT owner_user_id=a FROM public.teams WHERE team_id=ownerws) AND (SELECT owner_user_id=a FROM public.app_inventories WHERE inventory_id=ownerinv),'organization retains departing workspace and inventory');
 PERFORM pg_temp.account_check((SELECT owner_user_id=outsider FROM public.teams WHERE team_id=independent),'independent shared workspace retained for remaining Admin');
 PERFORM pg_temp.account_check(NOT EXISTS(SELECT 1 FROM public.teams WHERE team_id=solo),'unshared private workspace removed');
 PERFORM pg_temp.account_check(NOT EXISTS(SELECT 1 FROM public.app_inventories WHERE inventory_id=personal),'private inventory removed');
 PERFORM pg_temp.account_check(NOT EXISTS(SELECT 1 FROM public.team_memberships WHERE user_id=b) AND NOT EXISTS(SELECT 1 FROM public.app_organization_members WHERE user_id=b),'all memberships revoked');
 PERFORM pg_temp.account_check(public.findez_inventory_role(inv,b) IS NULL AND NOT public.findez_can_read_item_image(b,b||'/shared.jpg'),'deleted identity cannot access contents or photos');
 PERFORM pg_temp.account_check(public.findez_can_read_item_image(a,b||'/shared.jpg'),'surviving owner can still view shared photo');
 PERFORM pg_temp.account_check(NOT public.findez_can_read_item_image(outsider,b||'/shared.jpg'),'unrelated account still denied photo');
 SET CONSTRAINTS ALL DEFERRED;
 INSERT INTO public.app_organization_members VALUES(org,outsider,'admin');
 PERFORM public.findez_transfer_resource_owner(a,'organization',org,outsider,'Account deletion QA');
 PERFORM pg_temp.account_check(public.findez_prepare_account_deletion(a)->>'ready'='true','former org Owner can delete after ownership transfer');
 DELETE FROM auth.users WHERE id=a;
 PERFORM public.findez_finish_account_deletion(a);
 SET CONSTRAINTS ALL IMMEDIATE;
 PERFORM pg_temp.account_check((SELECT owner_user_id=outsider FROM public.app_organizations WHERE organization_id=org) AND EXISTS(SELECT 1 FROM public.items WHERE item_id=it),'owner transfer then deletion preserves organization and shared item');
 END LOOP;
END $$;
-- A previously successful preflight must not bypass a later ownership change.
DO $$
DECLARE a uuid:=gen_random_uuid(); org uuid;
BEGIN
 SET CONSTRAINTS ALL DEFERRED;
 INSERT INTO auth.users(id,email,email_confirmed_at) VALUES(a,a||'@example.invalid',now());
 PERFORM pg_temp.account_check(public.findez_prepare_account_deletion(a)->>'ready'='true','empty account preflight succeeds');
 org:=(public.findez_manage_collaboration(a,'organization_create','{"name":"Created after preflight"}')->>'organization_id')::uuid;
 BEGIN DELETE FROM auth.users WHERE id=a; RAISE EXCEPTION 'stale preflight removed new Owner'; EXCEPTION WHEN check_violation THEN NULL; END;
 PERFORM pg_temp.account_check(EXISTS(SELECT 1 FROM auth.users WHERE id=a) AND EXISTS(SELECT 1 FROM public.app_organizations WHERE organization_id=org),'Auth rechecks ownership after stale preflight');
 PERFORM pg_temp.account_check(NOT public.findez_finish_account_deletion(a),'stale receipt cannot authorize cleanup while identity exists');
END $$;
SELECT pg_temp.account_check(NOT has_function_privilege('authenticated','public.findez_prepare_account_deletion(uuid,jsonb)','EXECUTE'),'clients cannot delete another account');
SELECT pg_temp.account_check(NOT has_function_privilege('service_role','public.findez_preserve_shared_account_content()','EXECUTE'),'preservation hook cannot be called as a standalone RPC');
ROLLBACK;
